// for the repomap perf fixture; it references Func003_14_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func002_13_00(a, b int) int {
	if a > b {
		return Func003_14_00(a, b) + a
	}
	return Func003_14_00(b, a) - b
}

